// GENERATED by bundle.cjs from palette.js + dots.js. Do not edit.
// Read the collection's own colour tokens at runtime.
//
// A page or a figure may not carry a colour (AGENTS.md), and a canvas cannot
// read a CSS custom property. So the token is read from the computed style and
// handed to the shader as a uniform — the same discipline as `var(--tb-accent)`
// in CSS, one layer down.
//
// The tokens live on `body` (see assets/stylesheets/themes.css, sections 3-4):
// the bundle and the subject tint both resolve there, so `body` is the element
// to read. `data-theme` is on `html` and `data-md-color-scheme` is on `body`.

const TOKENS = [
  "paper",
  "ink",
  "ink-soft",
  "rule",
  "accent",
  "accent-light",
  "accent-dark",
  "link",
  "fig-warn",
  "fig-good",
  "fig-grid",
];

const FALLBACK = {
  paper: "#faf9f5",
  ink: "#1f1e1b",
  "ink-soft": "#5c5a54",
  rule: "#e6e3da",
  accent: "#2f6690",
  "accent-light": "#4a7fae",
  "accent-dark": "#24506f",
  link: "#23577d",
  "fig-warn": "#a3402f",
  "fig-good": "#2c744a",
  "fig-grid": "#85837d",
};

let scratch = null;

/** Any CSS colour -> [r, g, b] in 0..1, via a 1x1 2D canvas. */
function toRgb(color, fallback = [0, 0, 0]) {
  if (!scratch) {
    scratch = document.createElement("canvas");
    scratch.width = 1;
    scratch.height = 1;
  }
  const ctx = scratch.getContext("2d", { willReadFrequently: true });
  if (!ctx) return fallback;
  ctx.fillStyle = "#010203"; // in case `color` is not a valid CSS colour
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, 1, 1);
  const d = ctx.getImageData(0, 0, 1, 1).data;
  return [d[0] / 255, d[1] / 255, d[2] / 255];
}

/** The tokens as strings, straight from the cascade. */
function readPalette(root = document.body || document.documentElement) {
  const cs = getComputedStyle(root);
  const out = {};
  for (const name of TOKENS) {
    out[name] = cs.getPropertyValue(`--tb-${name}`).trim() || FALLBACK[name];
  }
  return out;
}

/** The tokens as linear-ish RGB triples for a shader. */
function readPaletteRgb(root) {
  const tokens = readPalette(root);
  const out = { tokens };
  for (const name of TOKENS) out[camel(name)] = toRgb(tokens[name], toRgb(FALLBACK[name]));
  return out;
}

function camel(name) {
  return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

/**
 * Call `cb` whenever the reader changes bundle or scheme.
 *
 * The pipeline sets `data-theme` on `html` and `data-md-color-scheme` on `body`
 * before first paint, and the Settings runtime rewrites both. Nothing else
 * signals the change, so the two attributes are the observable.
 */
function watchPalette(cb) {
  let queued = false;
  const fire = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => {
      queued = false;
      cb(readPaletteRgb());
    });
  };
  const observer = new MutationObserver(fire);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  if (document.body) {
    observer.observe(document.body, { attributes: true, attributeFilter: ["data-md-color-scheme"] });
  }
  return () => observer.disconnect();
}


// Prototype: the floor. A small Canvas 2D field of drifting dots.
//
// This is what "a very small canvas" means in practice: no shader, no
// framebuffer, a few dozen draw calls. If a background effect is wanted at all,
// this is the cheapest thing that still moves.


/**
 * @param {object} [opts]
 * @param {number} [opts.count=48] dots
 * @param {number} [opts.idleMs=2500]
 */
function mount(opts = {}) {
  const { count = 48, idleMs = 2500, className = "tb-bg-dots" } = opts;

  const canvas = document.createElement("canvas");
  canvas.className = className;
  canvas.setAttribute("aria-hidden", "true");
  Object.assign(canvas.style, {
    position: "fixed", inset: "0", width: "100%", height: "100%",
    pointerEvents: "none", zIndex: "-1", display: "block",
  });
  const ctx = canvas.getContext("2d", { alpha: true });
  if (!ctx) return null;

  (document.body || document.documentElement).appendChild(canvas);

  let palette = readPaletteRgb();
  const unwatch = watchPalette((next) => { palette = next; });

  function resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
    canvas.width = Math.max(1, Math.floor(canvas.clientWidth * dpr));
    canvas.height = Math.max(1, Math.floor(canvas.clientHeight * dpr));
  }
  resize();

  const dots = Array.from({ length: count }, (_, i) => ({
    x: Math.random(), y: Math.random(),
    vx: (Math.random() - 0.5) * 0.02,
    vy: (Math.random() - 0.5) * 0.02,
    r: 0.6 + (i % 3) * 0.35,
  }));

  function frameStep(dt) {
    const w = canvas.width;
    const h = canvas.height;
    if (w < 2 || h < 2) return;
    ctx.clearRect(0, 0, w, h);
    const [r, g, b] = palette.accent;
    ctx.fillStyle = `rgb(${Math.round(r * 255)} ${Math.round(g * 255)} ${Math.round(b * 255)})`;
    ctx.globalAlpha = 0.25;
    const a = w / h;
    for (const d of dots) {
      d.x += d.vx * dt;
      d.y += d.vy * dt;
      if (d.x < 0 || d.x > 1) d.vx *= -1;
      if (d.y < 0 || d.y > 1) d.vy *= -1;
      d.x = Math.min(1, Math.max(0, d.x));
      d.y = Math.min(1, Math.max(0, d.y));
      const px = (d.x * a > 1 ? d.x : d.x) * w;
      const py = d.y * h;
      ctx.beginPath();
      ctx.arc(px, py, d.r * (h / 800), 0, 6.2831853);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  let raf = 0;
  let running = false;
  let hidden = false;
  let lastInput = performance.now();
  let last = performance.now();
  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");
  const passes = [];

  function frame(now) {
    raf = 0;
    const dt = Math.min((now - last) / 1000, 1 / 30);
    last = now;
    const t0 = performance.now();
    frameStep(dt);
    passes.push(performance.now() - t0);
    if (passes.length > 600) passes.shift();
    schedule();
  }
  function schedule() {
    if (!running || hidden || reduced.matches) return;
    if (performance.now() - lastInput > idleMs) return;
    raf = requestAnimationFrame(frame);
  }
  function startLoop() { if (running) return; running = true; last = performance.now(); if (!raf) raf = requestAnimationFrame(frame); }
  function stopLoop() { running = false; if (raf) cancelAnimationFrame(raf); raf = 0; }
  function poke() { lastInput = performance.now(); startLoop(); }
  function onVisibility() { hidden = document.hidden; if (hidden) stopLoop(); else startLoop(); }
  function onReduced() { if (reduced.matches) { stopLoop(); frameStep(1 / 60); } else poke(); }

  window.addEventListener("pointermove", poke, { passive: true });
  window.addEventListener("pointerdown", poke, { passive: true });
  window.addEventListener("resize", resize, { passive: true });
  document.addEventListener("visibilitychange", onVisibility);
  reduced.addEventListener("change", onReduced);

  let intersection = null;
  if (typeof IntersectionObserver !== "undefined") {
    intersection = new IntersectionObserver((entries) => {
      if (entries.some((e) => e.isIntersecting)) startLoop(); else stopLoop();
    });
    intersection.observe(canvas);
  }

  frameStep(1 / 60);
  if (!reduced.matches) startLoop();

  return {
    canvas,
    stop() {
      stopLoop();
      unwatch();
      intersection?.disconnect();
      window.removeEventListener("pointermove", poke);
      window.removeEventListener("pointerdown", poke);
      window.removeEventListener("resize", resize);
      document.removeEventListener("visibilitychange", onVisibility);
      reduced.removeEventListener("change", onReduced);
      canvas.remove();
    },
    palette() { return palette; },
    stats() {
      const sorted = [...passes].sort((a, b) => a - b);
      return { passes: passes.length, running, looping: raf !== 0, hidden, reducedMotion: reduced.matches,
        submitMsMean: sorted.length ? sorted.reduce((a, b) => a + b, 0) / sorted.length : 0 };
    },
  };
}

window.__bgBoot = function () {
  const handle = mount(window.__bgOptions || {});
  window.__bgHandle = handle;
  window.__bgReady = true;
  return handle;
};
